// Read-only: generated by running Classic's own code (MallardLabs/Matchbox
// at 5c657b5: platform-contracts' formatApiKey and platform-server's
// hmacHex, exactly what Classic's developer console runs when it creates a
// key). Provenance and the generator are beside it in apps/developer.
import classicFixture from "../../developer/src/worker/fixtures/classic-5c657b5.json"
import { createApp } from "./app"
