// A key created by Classic's developer console keeps authenticating here,
// with no data migration. The key row is stored exactly as Classic's
// console writes it (its mbx_dev_api_keys columns, its stored HMAC), and is
// read through this API's real Supabase store: a real supabase-js client
// whose fetch is a small PostgREST stand-in over those rows. Requests go
// through the whole app (request id, auth, rate limit, route).

const fixtureSchema = z.object({
  peppers: z.object({ apiKey: z.string() }),
  apiKey: z.object({
    value: z.string(),
    parsed: z.object({
      kind: z.literal("secret"),
      environmentKind: z.literal("live"),
      prefix: z.string(),
    }),
    hash: z.string().regex(/^[0-9a-f]{64}$/),
  }),
  publishableKey: z.object({
    value: z.string(),
    hash: z.string().regex(/^[0-9a-f]{64}$/),
  }),
})

const classic = fixtureSchema.parse(classicFixture)
const pepper = classic.peppers.apiKey
const now = new Date("2026-09-30T12:00:00.000Z")

const ids = {
  app: "00000000-0000-4000-8000-0000000000a1",
  liveEnvironment: "00000000-0000-4000-8000-0000000000e1",
  testEnvironment: "00000000-0000-4000-8000-0000000000e2",
  secretKey: "00000000-0000-4000-8000-0000000000c1",
  publishableKey: "00000000-0000-4000-8000-0000000000c2",
  account: "00000000-0000-4000-8000-0000000000d1",
}

type Row = Record<string, unknown>

/**
 * Rows with Classic's columns (supabase/migrations/
 * 20260930000001_create_developer_platform_v2.sql at 5c657b5), the way
 * Classic's console inserts them (apps/developer-console/src/worker/store/
 * supabase-store.ts: environment_id, kind, name, prefix, secret_hash,
 * allowed_cidrs, created_by, expires_at; the rest are column defaults).
 */
function classicRows() {
  const app: Row = {
    id: ids.app,
    organization_id: "00000000-0000-4000-8000-0000000000f1",
    name: "Classic app",
    slug: "classic-app",
    description: null,
    logo_url: null,
    website_url: null,
    privacy_url: null,
    terms_url: null,
    support_email: null,
    status: "active",
    created_at: "2026-09-01T00:00:00+00:00",
    updated_at: "2026-09-01T00:00:00+00:00",
  }
  const environment = (id: string, kind: "live" | "test"): Row => ({
    id,
    app_id: ids.app,
    kind,
    network: kind === "live" ? "mezo" : "mezo-testnet",
    client_id: `client-${kind}`,
    client_type: "confidential",
    review_state: kind === "live" ? "approved" : "development",
    requested_scopes: ["gauge-profiles:read"],
    approved_scopes: kind === "live" ? ["gauge-profiles:read"] : [],
    scope_version: 1,
    sector_id: "classic-app",
    created_at: "2026-09-01T00:00:00+00:00",
    updated_at: "2026-09-01T00:00:00+00:00",
  })
  const key = (
    id: string,
    environmentId: string,
    kind: "secret" | "publishable",
    prefix: string,
    hash: string,
  ): Row => ({
    id,
    environment_id: environmentId,
    kind,
    name: `Classic ${kind} key`,
    prefix,
    secret_hash: hash,
    allowed_cidrs: [],
    created_by: ids.account,
    created_at: "2026-09-02T00:00:00+00:00",
    expires_at: null,
    last_used_at: null,
    revoked_at: null,
    rotated_from: null,
  })
  return {
    mbx_dev_apps: [app],
    mbx_dev_environments: [
      environment(ids.liveEnvironment, "live"),
      environment(ids.testEnvironment, "test"),
    ],
    mbx_dev_origins: [
      {
        environment_id: ids.testEnvironment,
        origin: "http://localhost:5173",
        created_at: "2026-09-01T00:00:00+00:00",
      },
    ],
    mbx_dev_api_keys: [
      key(
        ids.secretKey,
        ids.liveEnvironment,
        "secret",
        classic.apiKey.parsed.prefix,
        classic.apiKey.hash,
      ),
      key(
        ids.publishableKey,
        ids.testEnvironment,
        "publishable",
        // mbx_pk_test_<prefix>_<secret>
        classic.publishableKey.value.split("_")[3] ?? "",
        classic.publishableKey.hash,
      ),
    ],
    mbx_dev_quota_overrides: [] as Row[],
  }
}

type Tables = ReturnType<typeof classicRows>
type TableName = keyof Tables

/** How PostgREST embeds one table in another (Classic's foreign keys). */
const embeds: Record<
  string,
  { table: TableName; local: string; foreign: string; many: boolean }
> = {
  mbx_dev_environments: {
    table: "mbx_dev_environments",
    local: "environment_id",
    foreign: "id",
    many: false,
  },
  mbx_dev_apps: {
    table: "mbx_dev_apps",
    local: "app_id",
    foreign: "id",
    many: false,
  },
  mbx_dev_origins: {
    table: "mbx_dev_origins",
    local: "id",
    foreign: "environment_id",
    many: true,
  },
}

/** Splits a select list at top-level commas. */
function selectItems(select: string): string[] {
  const items: string[] = []
  let depth = 0
  let current = ""
  for (const char of select) {
    if (char === "(") depth += 1
    if (char === ")") depth -= 1
    if (char === "," && depth === 0) {
      items.push(current.trim())
      current = ""
    } else {
      current += char
    }
  }
  if (current.trim() !== "") items.push(current.trim())
  return items
}

/** Projects a row through a PostgREST select, resolving embeds. */
function project(tables: Tables, row: Row, select: string): Row | null {
  const out: Row = {}
  for (const item of selectItems(select)) {
    const embed = /^(\w+):(\w+)(!inner)?\((.*)\)$/s.exec(item)
    if (embed === null) {
      out[item] = row[item]
      continue
    }
    const [, alias = "", table = "", inner, inside = ""] = embed
    const relation = embeds[table]
    if (relation === undefined) throw new Error(`No relation ${table}`)
    const related = tables[relation.table].filter(
      (candidate: Row) => candidate[relation.foreign] === row[relation.local],
    )
    const projected = related
      .map((candidate: Row) => project(tables, candidate, inside))
      .filter((candidate): candidate is Row => candidate !== null)
    if (relation.many) {
      out[alias] = projected
    } else {
      const first = projected[0] ?? null
      if (first === null && inner !== undefined) return null
      out[alias] = first
    }
  }
  return out
}

/** A PostgREST stand-in: filters `eq` and `is.null`, offset and limit. */
function fakeSupabase(tables: Tables) {
  const requests: { method: string; table: string; url: URL; body: unknown }[] =
    []
  async function fetch(
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> {
    const url = new URL(input instanceof Request ? input.url : String(input))
    const method = init?.method ?? "GET"
    const table = url.pathname.replace("/rest/v1/", "")
    const body: unknown =
      typeof init?.body === "string" ? JSON.parse(init.body) : null
    requests.push({ method, table, url, body })
    if (!(table in tables)) return Response.json([], { status: 200 })
    const rows: Row[] = tables[table as TableName]
    const filters = [...url.searchParams].filter(
      ([name]) => !["select", "order", "offset", "limit"].includes(name),
    )
    const matching = rows.filter((row) =>
      filters.every(([name, condition]) =>
        condition === "is.null"
          ? row[name] === null
          : condition.startsWith("eq.")
            ? String(row[name]) === condition.slice(3)
            : true,
      ),
    )
    if (method === "PATCH") {
      for (const row of matching) Object.assign(row, body)
      return new Response(null, { status: 204 })
    }
    const offset = Number(url.searchParams.get("offset") ?? "0")
    const limit = Number(url.searchParams.get("limit") ?? "1000")
    const select = url.searchParams.get("select") ?? "*"
    const projected = matching
      .slice(offset, offset + limit)
      .map((row) => (select === "*" ? row : project(tables, row, select)))
      .filter((row) => row !== null)
    return Response.json(projected)
  }
  return { fetch, requests }
}

function countingLimiter() {
  const consumed: string[] = []
  const memory = createMemoryRateLimitClient(() => now.getTime())
  const client: RateLimitClient = {
    consume(key, policy) {
      consumed.push(key)
      return memory.consume(key, policy)
    },
  }
  return { client, consumed }
}

function harness(
  options: { pepper?: string; tables?: (tables: Tables) => void } = {},
) {
  const tables = classicRows()
  options.tables?.(tables)
  const supabase = fakeSupabase(tables)
  const limiter = countingLimiter()
  const background: Promise<unknown>[] = []
  const app = createApp({
    store: createSupabaseApiStore({
      supabase: createClient("https://classic.supabase.co", "service-role", {
        auth: { persistSession: false, autoRefreshToken: false },
        global: { fetch: supabase.fetch },
      }),
      logger: silentLogger,
    }),
    market: null,
    rateLimits: limiter.client,
    analytics: null,
    now: () => now,
    flags: { gaugeProfileApi: true },
    config: {
      apiKeyPepper: options.pepper ?? pepper,
      version: "classic-compat",
      environment: "test",
    },
    logger: silentLogger,
  })
  async function get(
    path: string,
    key: string,
    extra: { ip?: string; origin?: string } = {},
  ): Promise<Response> {
    const response = await app.request(
      `https://api.matchbox.markets${path}`,
      {
        headers: {
          Authorization: `Bearer ${key}`,
          "CF-Connecting-IP": extra.ip ?? "198.51.100.7",
          ...(extra.origin === undefined ? {} : { Origin: extra.origin }),
        },
      },
      undefined,
      {
        waitUntil(task: Promise<unknown>) {
          background.push(task)
        },
        passThroughOnException() {},
        props: {},
      },
    )
    await Promise.all(background.splice(0))
    return response
  }
  return { get, tables, supabase, limiter }
}

async function code(response: Response): Promise<string> {
  return errorBodySchema.parse(await response.json()).error.code
}

/** The key with one character of its secret changed. */
function tampered(key: string): string {
  const last = key.at(-1) === "s" ? "t" : "s"
  return `${key.slice(0, -1)}${last}`
}

let h: ReturnType<typeof harness>

beforeEach(() => {
  h = harness()
})

describe("a Classic-created API key", () => {
  it("authenticates a real /v1 request with Classic's stored hash", async () => {
    const response = await h.get("/v1/networks", classic.apiKey.value)
    expect(response.status).toBe(200)
    // Looked up by its prefix with the columns Classic's API reads.
    const lookup = h.supabase.requests.find(
      (request) =>
        request.table === "mbx_dev_api_keys" &&
        request.url.searchParams.get("prefix") ===
          `eq.${classic.apiKey.parsed.prefix}`,
    )
    // Classic's developer-api select, verbatim (supabase-js drops spaces).
    expect(lookup?.url.searchParams.get("select")).toBe(
      "id, kind, prefix, secret_hash, allowed_cidrs, expires_at, revoked_at, environment:mbx_dev_environments!inner(id, kind, network, review_state, approved_scopes, app:mbx_dev_apps!inner(id, status), origins:mbx_dev_origins(origin))".replace(
        /\s/g,
        "",
      ),
    )
  })

  it("records last use on the key row, by key id", async () => {
    await h.get("/v1/networks", classic.apiKey.value)
    const patch = h.supabase.requests.find(
      (request) => request.method === "PATCH",
    )
    expect(patch?.table).toBe("mbx_dev_api_keys")
    expect(patch?.url.searchParams.get("id")).toBe(`eq.${ids.secretKey}`)
    expect(patch?.body).toEqual({ last_used_at: now.toISOString() })
    expect(h.tables.mbx_dev_api_keys[0]?.last_used_at).toBe(now.toISOString())
  })

  it("rate limits by environment, never by an IP bucket, once verified", async () => {
    await h.get("/v1/networks", classic.apiKey.value)
    expect(h.limiter.consumed).toEqual([`env:${ids.liveEnvironment}:secret`])
  })

  it("rejects the key with one character changed", async () => {
    const response = await h.get("/v1/networks", tampered(classic.apiKey.value))
    expect(response.status).toBe(401)
    expect(await code(response)).toBe("unauthorized")
    // A failed key spends the caller's IP bucket, not the environment's.
    expect(h.limiter.consumed).toEqual(["ip:198.51.100.0/24"])
  })

  it("rejects the right key under a different pepper", async () => {
    const other = harness({ pepper: `${pepper}-rotated` })
    const response = await other.get("/v1/networks", classic.apiKey.value)
    expect(response.status).toBe(401)
  })

  it("rejects a revoked row", async () => {
    const revoked = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_api_keys[0]
        if (row !== undefined) row.revoked_at = "2026-09-29T00:00:00+00:00"
      },
    })
    const response = await revoked.get("/v1/networks", classic.apiKey.value)
    expect(response.status).toBe(401)
  })

  it("rejects an expired row and accepts one not yet expired", async () => {
    const expired = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_api_keys[0]
        if (row !== undefined) row.expires_at = "2026-09-30T11:59:59+00:00"
      },
    })
    expect(
      (await expired.get("/v1/networks", classic.apiKey.value)).status,
    ).toBe(401)
    const later = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_api_keys[0]
        if (row !== undefined) row.expires_at = "2026-12-31T00:00:00+00:00"
      },
    })
    expect((await later.get("/v1/networks", classic.apiKey.value)).status).toBe(
      200,
    )
  })

  it("rejects a key whose environment is not the kind its string says", async () => {
    const swapped = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_api_keys[0]
        if (row !== undefined) row.environment_id = ids.testEnvironment
      },
    })
    expect(
      (await swapped.get("/v1/networks", classic.apiKey.value)).status,
    ).toBe(401)
  })

  it("requires an approved live environment with gauge-profiles:read", async () => {
    const unapproved = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_environments[0]
        if (row !== undefined) row.review_state = "submitted"
      },
    })
    const response = await unapproved.get("/v1/networks", classic.apiKey.value)
    expect(response.status).toBe(403)
    expect(await code(response)).toBe("forbidden")
    const unscoped = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_environments[0]
        if (row !== undefined) row.approved_scopes = ["openid"]
      },
    })
    expect(
      (await unscoped.get("/v1/networks", classic.apiKey.value)).status,
    ).toBe(403)
  })

  it("refuses a suspended app", async () => {
    const suspended = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_apps[0]
        if (row !== undefined) row.status = "suspended"
      },
    })
    expect(
      (await suspended.get("/v1/networks", classic.apiKey.value)).status,
    ).toBe(403)
  })

  it("enforces the key's CIDR allow-list", async () => {
    const allowListed = harness({
      tables: (tables) => {
        const row = tables.mbx_dev_api_keys[0]
        if (row !== undefined) row.allowed_cidrs = ["203.0.113.0/24"]
      },
    })
    expect(
      (
        await allowListed.get("/v1/networks", classic.apiKey.value, {
          ip: "203.0.113.9",
        })
      ).status,
    ).toBe(200)
    const outside = await allowListed.get(
      "/v1/networks",
      classic.apiKey.value,
      {
        ip: "198.51.100.7",
      },
    )
    expect(outside.status).toBe(403)
    expect(await code(outside)).toBe("forbidden")
  })

  it("refuses a secret key from a browser origin", async () => {
    const response = await h.get("/v1/networks", classic.apiKey.value, {
      origin: "https://app.example.com",
    })
    expect(response.status).toBe(403)
    expect(await code(response)).toBe("origin_not_allowed")
  })

  it("serves every readable network to the key and rejects an unknown one", async () => {
    // Classic gives every key every network; the environment's network is
    // read but does not restrict routes.
    const testnet = await h.get(
      "/v1/gauge-profiles/mezo-testnet/0x0000000000000000000000000000000000000001",
      classic.apiKey.value,
    )
    expect(testnet.status).toBe(404)
    const unknown = await h.get(
      "/v1/gauge-profiles/ethereum/0x0000000000000000000000000000000000000001",
      classic.apiKey.value,
    )
    expect(unknown.status).toBe(403)
    expect(await code(unknown)).toBe("network_not_allowed")
  })
})

describe("a Classic-created publishable key", () => {
  it("authenticates from its registered origin only", async () => {
    const ok = await h.get("/v1/networks", classic.publishableKey.value, {
      origin: "http://localhost:5173",
    })
    expect(ok.status).toBe(200)
    expect(ok.headers.get("Access-Control-Allow-Origin")).toBe(
      "http://localhost:5173",
    )
    // Publishable keys also spend a per-key, per-IP-prefix bucket.
    expect(h.limiter.consumed).toEqual([
      `pk:${ids.publishableKey}:198.51.100.0/24`,
      `env:${ids.testEnvironment}:publishable`,
    ])
    const elsewhere = await h.get(
      "/v1/networks",
      classic.publishableKey.value,
      {
        origin: "https://evil.example",
      },
    )
    expect(elsewhere.status).toBe(403)
    expect(await code(elsewhere)).toBe("origin_not_allowed")
  })
})

describe("Classic's pepper", () => {
  it("passes this Worker's API_KEY_PEPPER rule (32 characters or more)", () => {
    const result = parseWorkerEnv({
      RATE_LIMITER: { idFromName() {}, get() {} },
      SUPABASE_URL: "https://classic.supabase.co",
      SUPABASE_SERVICE_ROLE_KEY: "service-role",
      API_KEY_PEPPER: pepper,
    })
    expect(result.ok).toBe(true)
  })
})
